content.content:
1	'use client';
2	
3	import dynamic from 'next/dynamic';
4	import { useRef, useState } from 'react';
5	import { useRouter } from 'next/navigation';
6	import type { LabelExtractionResponse, ReceiptExtractionResponse } from '@/contracts/api';
7	import type { Product, ProductSource } from '@/contracts/domain';
8	import { Badge, Button, Card, useToast } from '@/components/ui';
9	import { pantryApi } from '@/features/pantry/api';
10	import { ProductForm, type ProductFormValues } from '@/features/pantry/ProductForm';
11	import { scanApi } from './api';
12	import type { ScannedCode } from './BarcodeScanner';
13	import { ExpiryCapture } from './ExpiryCapture';
14	import { PhotoCapture } from './PhotoCapture';
15	import { draftToFormInitial, productToFormInitial } from './pure';
16	import { ReceiptReview, type ReceiptLineInput } from './ReceiptReview';
17	
18	// SPEC UF2/UF3: scan → found card, or not found → label photo → confirm. The manual form is
19	// reachable from every step. Scanning a receipt is the default entry point; barcode scan and
20	// manual entry are offered next to it.
21	
22	const BarcodeScanner = dynamic(() => import('./BarcodeScanner').then((m) => m.BarcodeScanner), { ssr: false });
23	
24	type Step =
25	  | { kind: 'receipt_capture'; message?: string }
26	  | { kind: 'receipt_review'; response: ReceiptExtractionResponse }
27	  | { kind: 'scan'; notice?: string; ignoreGtin?: string }
28	  | { kind: 'looking' }
29	  | { kind: 'found'; product: Product }
30	  | { kind: 'not_found'; gtin: string }
31	  | { kind: 'label'; gtin: string | null; message?: string }
32	  | { kind: 'draft'; response: LabelExtractionResponse }
33	  | { kind: 'manual'; gtin: string | null };
34	
35	function FoundCard({ product }: { product: Product }) {
36	  const kcal = product.per100.energyKcal;
37	  const per = product.basis === '100ml' ? '100 ml' : '100 g';
38	  const size = product.packageQuantity?.text ?? (product.packageQuantity ? `${product.packageQuantity.value} ${product.packageQuantity.unit}` : null);
39	  return (
40	    <Card className="flex gap-4">
41	      {product.imageUrl?.startsWith('https://') && (
42	        // eslint-disable-next-line @next/next/no-img-element -- third-party product photo, any host
43	        <img src={product.imageUrl} alt="" className="h-24 w-24 shrink-0 rounded-xl object-contain" />
44	      )}
45	      <div className="min-w-0">
46	        <h2 className="font-display text-xl font-semibold">{product.name}</h2>
47	        {product.brand && <p className="text-sm text-muted">{product.brand}</p>}
48	        <p className="mt-1 text-sm">
49	          {kcal != null ? `${Math.round(kcal)} kcal per ${per}` : 'No calorie data'}
50	          {size ? ` · ${size}` : ''}
51	        </p>
52	        <p className="mt-1 text-xs text-muted">Product data: Open Food Facts (ODbL)</p>
53	      </div>
54	    </Card>
55	  );
56	}
57	
58	export function AddProductFlow() {
59	  const router = useRouter();
60	  const toast = useToast();
61	  const [step, setStep] = useState<Step>({ kind: 'receipt_capture' });
62	  const [readingLabel, setReadingLabel] = useState(false);
63	  const [readingReceipt, setReadingReceipt] = useState(false);
64	  // Bumped whenever the user moves on, so a slow response can't replace what they're doing now.
65	  const latestRequest = useRef(0);
66	
67	  async function lookup(code: ScannedCode) {
68	    const request = ++latestRequest.current;
69	    setStep({ kind: 'looking' });
70	    try {
71	      // lookupCode, not gtin: it keeps an EAN-8 as 8 digits for the providers.
72	      const r = await scanApi.lookup(code.lookupCode);
73	      if (request !== latestRequest.current) return;
74	      if (r.status === 'found') setStep({ kind: 'found', product: r.product });
75	      else if (r.status === 'not_found') setStep({ kind: 'not_found', gtin: r.gtin });
76	      else setStep({ kind: 'scan', notice: "That barcode doesn't look valid", ignoreGtin: code.gtin });
77	    } catch (e) {
78	      if (request !== latestRequest.current) return;
79	      setStep({ kind: 'scan', notice: e instanceof Error ? e.message : 'Could not look up that barcode.', ignoreGtin: code.gtin });
80	    }
81	  }
82	
83	  async function readLabel(photos: Blob[], gtin: string | null) {
84	    const request = ++latestRequest.current;
85	    setReadingLabel(true);
86	    try {
87	      const response = await scanApi.readLabel(photos, gtin);
88	      if (request !== latestRequest.current) return;
89	      if (response.isFoodProduct) setStep({ kind: 'draft', response });
90	      else setStep({ kind: 'label', gtin, message: "That doesn't look like a food product. Try another photo, or enter it by hand." });
91	    } catch (e) {
92	      if (request !== latestRequest.current) return;
93	      setStep({ kind: 'label', gtin, message: e instanceof Error ? e.message : "We couldn't read that photo." });
94	    } finally {
95	      setReadingLabel(false);
96	    }
97	  }
98	
99	  async function save(values: ProductFormValues, gtin: string | null, source: ProductSource, userVerified: boolean) {
100	    await pantryApi.create({ ...values, gtin, source, userVerified });
101	    toast(`${values.name} added`);
102	    router.push('/pantry');
103	    router.refresh();
104	  }
105	
106	  async function readReceipt(photos: Blob[]) {
107	    const request = ++latestRequest.current;
108	    setReadingReceipt(true);
109	    try {
110	      const response = await scanApi.readReceipt(photos);
111	      if (request !== latestRequest.current) return;
112	      if (response.items.length === 0) {
113	        setStep({ kind: 'receipt_capture', message: "We couldn't find any food items on that receipt. Try another photo, or add items by hand." });
114	      } else {
115	        setStep({ kind: 'receipt_review', response });
116	      }
117	    } catch (e) {
118	      if (request !== latestRequest.current) return;
119	      setStep({ kind: 'receipt_capture', message: e instanceof Error ? e.message : "We couldn't read that receipt." });
120	    } finally {
121	      setReadingReceipt(false);
122	    }
123	  }
124	
125	  async function saveReceiptItems(items: ReceiptLineInput[]): Promise<{ failedNames: string[] }> {
126	    const failedNames: string[] = [];
127	    let addedCount = 0;
128	    for (const item of items) {
129	      try {
130	        await pantryApi.create({
131	          name: item.name,
132	          brand: null,
133	          quantity: item.quantity,
134	          displayUnit: item.displayUnit,
135	          gramsPerUnit: null,
136	          densityGPerMl: null,
137	          expiryDate: null,
138	          expirySource: null,
139	          nutritionBasis: 'unit',
140	          nutrition: null,
141	          servingSizeBase: null,
142	          allergenTags: [],
143	          gtin: null,
144	          source: 'gemini_receipt',
145	          userVerified: true,
146	        });
147	        addedCount++;
148	      } catch {
149	        failedNames.push(item.name);
150	      }
151	    }
152	    if (addedCount > 0) toast(`${addedCount} item${addedCount === 1 ? '' : 's'} added`);
153	    if (failedNames.length === 0) {
154	      router.push('/pantry');
155	      router.refresh();
156	    }
157	    return { failedNames };
158	  }
159	
160	  const rescan = () => setStep({ kind: 'scan' });
161	  const goReceipt = () => setStep({ kind: 'receipt_capture' });
162	  const goManual = () => setStep({ kind: 'manual', gtin: null });
163	  const expirySlot = (apply: Parameters<typeof ExpiryCapture>[0]['onConfirm']) => <ExpiryCapture onConfirm={apply} />;
164	
165	  return (
166	    <div className="grid gap-6">
167	      {step.kind === 'receipt_capture' && (
168	        <Card>
169	          <h2 className="font-display text-xl font-semibold">Scan your receipt</h2>
170	          <p className="mb-4 mt-1 text-sm text-muted">Take a photo of the receipt. Up to 3 photos for a long one.</p>
171	          <PhotoCapture max={3} busy={readingReceipt} addLabel="Take photo" submitLabel="Read receipt" onSubmit={(p) => void readReceipt(p)} />
172	          {step.message && (
173	            <p role="alert" className="mt-4 rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
174	              {step.message}
175	            </p>
176	          )}
177	          <div className="mt-4 flex flex-wrap gap-3">
178	            <Button variant="secondary" onClick={rescan}>
179	              Scan barcode
180	            </Button>
181	            <Button variant="ghost" onClick={goManual}>
182	              Add manually
183	            </Button>
184	          </div>
185	        </Card>
186	      )}
187	
188	      {step.kind === 'receipt_review' && (
189	        <ReceiptReview response={step.response} onConfirm={saveReceiptItems} onCancel={goReceipt} />
190	      )}
191	
192	      {step.kind === 'scan' && <BarcodeScanner onCode={(c) => void lookup(c)} notice={step.notice} ignoreGtin={step.ignoreGtin} />}
193	
194	      {step.kind === 'looking' && (
195	        <p role="status" className="text-sm text-muted">
196	          Looking up that barcode…
197	        </p>
198	      )}
199	
200	      {step.kind === 'found' && (
201	        <>
202	          <FoundCard product={step.product} />
203	          <ProductForm
204	            key={step.product.gtin}
205	            initial={productToFormInitial(step.product)}
206	            expirySlot={expirySlot}
207	            submitLabel="Add to pantry"
208	            onCancel={rescan}
209	            onSubmit={(v) => save(v, step.product.gtin, step.product.source, false)}
210	          />
211	        </>
212	      )}
213	
214	      {step.kind === 'not_found' && (
215	        <Card>
216	          <h2 className="font-display text-xl font-semibold">We couldn&apos;t find this product.</h2>
217	          <div className="mt-4 flex flex-wrap gap-3">
218	            <Button onClick={() => setStep({ kind: 'label', gtin: step.gtin })}>Take photo of label</Button>
219	            <Button variant="secondary" onClick={() => setStep({ kind: 'manual', gtin: step.gtin })}>
220	              Enter manually
221	            </Button>
222	            <Button variant="ghost" onClick={rescan}>
223	              Scan another
224	            </Button>
225	          </div>
226	        </Card>
227	      )}
228	
229	      {step.kind === 'label' && (
230	        <Card>
231	          <h2 className="font-display text-xl font-semibold">Photos of the product</h2>
232	          <p className="mb-4 mt-1 text-sm text-muted">Add the front and the nutrition table, up to 3 photos.</p>
233	          <PhotoCapture
234	            max={3}
235	            busy={readingLabel}
236	            addLabel="Take photo"
237	            submitLabel="Read label"
238	            onSubmit={(p) => void readLabel(p, step.gtin)}
239	          />
240	          {step.message && (
241	            <p role="alert" className="mt-4 rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
242	              {step.message}
243	            </p>
244	          )}
245	        </Card>
246	      )}
247	
248	      {step.kind === 'draft' &&
249	        (() => {
250	          const { initial, nutritionDropped } = draftToFormInitial(step.response.draft);
251	          return (
252	            <>
253	              {nutritionDropped && (
254	                <p className="rounded-xl bg-warn-soft px-3 py-2 text-sm">
255	                  The label&apos;s serving weight couldn&apos;t be read, so its nutrition values were left out.
256	                </p>
257	              )}
258	              <ProductForm
259	                initial={initial}
260	                flaggedFields={step.response.flaggedFields}
261	                badge={<Badge tone="ai">Read by AI, please confirm</Badge>}
262	                expirySlot={expirySlot}
263	                submitLabel="Confirm"
264	                onCancel={rescan}
265	                onSubmit={(v) => save(v, step.response.draft.gtin, 'gemini_photo', true)}
266	              />
267	            </>
268	          );
269	        })()}
270	
271	      {step.kind === 'manual' && (
272	        <ProductForm expirySlot={expirySlot} submitLabel="Add to pantry" onCancel={rescan} onSubmit={(v) => save(v, step.gtin, 'manual', true)} />
273	      )}
274	
275	      {step.kind !== 'manual' &&
276	        step.kind !== 'draft' &&
277	        step.kind !== 'not_found' &&
278	        step.kind !== 'receipt_capture' &&
279	        step.kind !== 'receipt_review' && (
280	          <div className="flex flex-wrap gap-3">
281	            {step.kind === 'scan' && (
282	              <Button variant="ghost" onClick={goReceipt}>
283	                Scan receipt instead
284	              </Button>
285	            )}
286	            <Button
287	              variant="ghost"
288	              onClick={() => {
289	                latestRequest.current++;
